from typing import List, Any, Dict
from datetime import datetime
from Backend.core.evidence_dtos.session import SessionLiquidityEvidence, SessionLiquidityObject, SessionBoundaryType

class SessionLiquiditySelectionRule:
    """
    Selection Phase: Filters valid session boundaries based on configuration.
    """
    def __init__(self, rule_id: str = "RULE-SESS-LIQ-SEL-001"):
        self.rule_id = rule_id

    def select(self, available_boundaries: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
        # In a real environment, this selects valid boundary inputs generated by the Session Engine
        selected = []
        for boundary in available_boundaries:
            if boundary.get("price") is not None and boundary.get("session_id") is not None:
                selected.append(boundary)
        return selected

class SessionLiquidityConstructionRule:
    """
    Construction Phase: Builds the final SessionLiquidityObject.
    """
    def __init__(self, rule_id: str = "RULE-SESS-LIQ-CON-001"):
        self.rule_id = rule_id

    def construct(self, selected_boundaries: List[Dict[str, Any]], current_timestamp: datetime) -> List[SessionLiquidityObject]:
        from Backend.core.evidence_dtos.base import PlatformIdentity, LineageRecord
        
        objects = []
        for boundary in selected_boundaries:
            evidence = SessionLiquidityEvidence(
                session_id=boundary.get("session_id", ""),
                boundary_type=SessionBoundaryType(boundary.get("boundary_type", "HIGH")),
                price=boundary.get("price", 0.0),
                timestamp=current_timestamp,
                origin_bar_timestamp=boundary.get("origin_bar_timestamp", current_timestamp),
                calendar_id=boundary.get("calendar_id", ""),
                window_start=boundary.get("window_start", current_timestamp),
                window_end=boundary.get("window_end", current_timestamp)
            )
            
            obj = SessionLiquidityObject(
                identity=PlatformIdentity(
                    owner_family="SessionLiquidity",
                    calendar=evidence.calendar_id,
                    session=evidence.session_id,
                    boundary=evidence.boundary_type.value
                ),
                lineage=LineageRecord(
                    platform="Platform10",
                    family="LiquidityObjects",
                    capability="SessionLiquidity",
                    source_dto_uuids=[], 
                    source_rule_ids=[self.rule_id],
                    source_engine_id="SessionLiquidityEngine",
                    parent_object_uuids=[],
                    source_revision="1.0.0",
                    version="1.0.0",
                    replay_id="",
                    timestamp=current_timestamp
                ),
                evidence=evidence
            )
            objects.append(obj)
            
        return objects
